/** Every MK-CF-F record in the code, read from the code: the header rule the header writer prints directly above each function
 *  (the one the card builder and guard_function_descriptions read), with the file that declares it. */
function headersInCode(): Map<string, string> {
  const out = new Map<string, string>();
  const walk = (dir: string) => {
    for (const f of fs.readdirSync(dir, { withFileTypes: true })) {
      if (f.name === 'node_modules') continue;
      const p = path.join(dir, f.name);
      if (f.isDirectory()) { walk(p); continue; }
      if (!/\.tsx?$/.test(f.name) || /\.test\./.test(f.name)) continue;
      for (const m of fs.readFileSync(p, 'utf8').matchAll(/\/\* ─ (MK-CF-F-\d{3}) ─/g)) if (!out.has(m[1])) out.set(m[1], path.relative(ROOT, p));
    }
  };
  for (const c of ['src', 'MoneyKeel/functions', 'Calculation Module code/engines']) walk(path.join(ROOT, c));
  return out;
}

describe('every Cash flow function traces to its proof in one hop (step 3.c)', () => {
  // THE GUARD PROVES IT LOOKED (2026-10-24). It checked a typed floor of 201 and nothing else, so 22 functions numbered after the
  // table was printed (MK-CF-F-216 to 237) were missing and the test still passed until one row was removed. It now reads every
  // MK-CF-F record in the code — the header rule printed above each function — and the table must be exactly that set.
  it('the table covers every Cash flow function in the code — and says how many', () => {
    const code = headersInCode();
    console.log(`cf_function_trace: ${code.size} MK-CF-F records in the code, ${FUNCTIONS.length} rows in the table`);
    // 222 on 2026-10-24, 227 the same day once five example helpers left O for F — a floor that only ever rises, except by a
    // retirement, which lowers it by the true number: 225 on 2026-10-25, MK-CF-F-048 effectiveTaxRate and MK-CF-F-098
    // progressiveMonthlyTax retired (FIX-TAX; their numbers stay on the register's retired list); 224 the same day, MK-CF-F-020
    // cashflowYear retired (FIX-BILLS — a second twelve-month table with no production caller; the number stays retired); 223
    // the same day, MK-CF-F-210 annualOfSource retired (FIX-INCOME-B — no production caller; the number stays retired)
    // the same day, MK-CF-F-210 annualOfSource retired (FIX-INCOME-B — no production caller; the number stays retired); 262 on
    // 2026-10-26, the 39 functions written in the 2026-10-25 fix wave numbered (MK-CF-F-243 to 281, PF-TOOLS)
    // 266 the same day: growthUsed (CLEANUP-LEFT), and three numbered by hand — PLANNED_GROUP_WORDS, federalBracketForComparison,
    // accountIncomeIn (the lead's instruction)
    expect(code.size).toBeGreaterThanOrEqual(298);   // 298 on 2026-11-02 (PF-TOOLS round 6: MK-CF-F-314 to 317); 294 earlier that day (MK-CF-F-313 wageRefusalOf, round 5); 293 at the end of 2026-11-01 (PF-TOOLS: MK-CF-F-297 to 312, round 4); 277 earlier that day (MK-CF-F-295 debtLoad, 296 its example helper); 275 on 2026-10-30 (PF-TOOLS: MK-CF-F-286 to 294, the fix wave's nine)
    expect(FUNCTIONS.length).toBeGreaterThanOrEqual(298);
    expect(new Set(FUNCTIONS.map((r) => r[0])).size).toBe(FUNCTIONS.length);
    const table = new Set(FUNCTIONS.map((r) => r[0]));
    expect([...code.keys()].filter((id) => !table.has(id)).sort()).toEqual([]);   // in the code, missing from the table
    expect([...table].filter((id) => !code.has(id)).sort()).toEqual([]);          // in the table, gone from the code
    expect(FUNCTIONS.filter(([id, src]) => code.get(id) !== src).map(([id, src]) => `${id}: the table says ${src}, the code declares it in ${code.get(id)}`)).toEqual([]);
  });

  it('each identifier really is in the file this table names', () => {
    const wrong: string[] = [];
    for (const [id, src] of FUNCTIONS) {
      const p = path.join(ROOT, src);
      if (!fs.existsSync(p) || !fs.readFileSync(p, 'utf8').includes(id)) wrong.push(`${id} → ${src}`);
    }
    expect(wrong).toEqual([]);
  });

  it('each function names a test that exists', () => {
    const missing = FUNCTIONS.filter(([, , t]) => !t || !fs.existsSync(path.join(ROOT, t)))
      .map(([id, src]) => `${id} in ${src} — no test exercises this file`);
    expect(missing).toEqual([]);
  });
});
